  "claims": [
    {
      "claim": "The closest structural context, a pyrazolopyrimidinone with a pyridine sulfonamide piperazine, showed 34% absolute oral bioavailability in fasted healthy volunteers, directly supporting F >= 20% for a sulfonamide-linked basic amine on a fused lactam scaffold.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Ziprasidone, a fused lactam with a basic piperazine, had 30% oral bioavailability in the fasted state and about 60% in fed states, all above the 20% threshold.",
      "card_ids": ["C01", "C06", "C12", "C14"]
    },
    {
      "claim": "Praziquantel, an isoquinolinone-type scaffold, retained 27.2 ± 5.4% oral bioavailability even in cirrhotic patients, supporting positive oral exposure for isoquinolinone-related structures.",
      "card_ids": ["C03"]
    },
    {
      "claim": "Additional positive fasted-state absolute bioavailability records (niraparib ~73%, didanosine 29 ± 6%) reinforce that the training contexts are uniformly above threshold, although they are less structurally similar to the query.",
      "card_ids": ["C08", "C05", "C09"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C01", "C02", "C03", "C04", "C05", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15", "C16", "C17"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific oral bioavailability measurement is available.",
    "No human PK, formulation, or prandial-state data for the exact query molecule are supplied.",
    "Metabolic stability, first-pass extraction, and transporter/efflux behavior for the query are not directly measured.",
    "The query's very low neutral fraction and logD -1.42 raise permeability uncertainty, but this is not affirmative evidence of F < 20%."
  ],
  "decision_summary": "All L1 gold-context records are at or above the 20% absolute oral bioavailability threshold, and the closest structural contexts (sulfonamide-linked basic amine on a fused lactam; isoquinolinone-type lactam) report F values of 27-34% in fasted or diseased populations. The physicochemical prior is mixed but does not provide affirmative evidence for low F. Therefore F >= 20% is better supported, and the prediction is high with moderate confidence."
}

